use vstd::prelude::*;

verus! {

spec fn seq_eq_append(a: Seq<i32>, b: i32, res: Seq<i32>) -> bool {
    // The result sequence equals the input sequence 'a' concatenated with [b]
    res == a + seq![b]
}

/// Returns a new vector which is the vector `a` with an element `b` appended at the end.
/// The input vector `a` is not modified.
/// The order of all elements from `a` is preserved, and `b` is the last element.
fn append(a: &Vec<i32>, b: i32) -> Vec<i32>
    ensures
        // The resulting vector's sequence is exactly the input's sequence appended with b
        seq_eq_append(a@, b, ret@),
{
    let mut res = Vec::<i32>::new();
    let n = a.len();
    // Copy all elements from a into res
    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            res@ == a@[0..i],
            seq_eq_append(a@, b, res@ + seq![b]) || i < n, // for loop in progress or end
        decreases n - i,
    {
        res.push(a[i]);
        i = i + 1;
    }
    // Now append the given element b
    res.push(b);

    // Prove the result equals a + [b]
    assert(res@ == a@ + seq![b]);

    res
}

}

